    if style == "long":
        month = info["months"][value.month - 1]
        if info["order"] == "mdy":
            return f"{month} {value.day}, {value.year}"
        if info["order"] == "ymd":
            return f"{value.year} {month} {value.day}"
        return f"{value.day} {month} {value.year}"
