def display_width(text: str) -> int:
    """Number of terminal columns the text takes (wide East Asian characters count 2)."""
    cached = _WIDTH_CACHE.get(text)
    if cached is not None:
        return cached
    width = 0
    for ch in text:
        if unicodedata.combining(ch):
