import ast, os, sys, inspect, importlib.util, glob
sys.path.insert(0, "/app")
ROOT = "/app/tally/reports"

# ---- static
files = [p for p in glob.glob(ROOT + "/**/*.py", recursive=True)]
LAYER = {"errors": 0, "tables": 0, "state": 0, "system": 0, "formatting": 1, "model": 1, "loading": 2,
         "aggregate": 3, "renderers": 4, "cli": 5}
def modname(p):
    rel = os.path.relpath(p, "/app")[:-3].replace("/", ".")
    return rel[:-9] if rel.endswith(".__init__") else rel
mods = {modname(p): p for p in files}
def layer(m):
    parts = m.split(".")
    return 6 if len(parts) == 2 else LAYER[parts[2]]
bad = 0
def err(*a):
    global bad
    bad += 1
    print("FAIL", *a)
graph = {}
for m, p in mods.items():
    src = open(p, encoding="utf-8").read()
    n = src.count("\n") + (0 if src.endswith("\n") else 1)
    if n > 400: err("size", m, n)
    tree = ast.parse(src)
    deps = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for a in node.names:
                if a.name.startswith("tally"):
                    deps.add(a.name)
                if a.name in ("importlib",): err("importlib", m)
        elif isinstance(node, ast.ImportFrom):
            if node.level:
                pkg = m.split(".") if p.endswith("__init__.py") else m.split(".")[:-1]
                base = pkg[: len(pkg) - node.level + 1]
                full = ".".join(base + ([node.module] if node.module else []))
            else:
                full = node.module
            if full == "importlib": err("importlib", m)
            if full and full.split(".")[0] == "tally":
                if not full.startswith("tally.reports"):
                    err("outside import", m, full)
                for a in node.names:
                    cand = full + "." + a.name
                    if cand in mods:
                        deps.add(cand)
                    else:
                        deps.add(full)
                        if a.name.startswith("_") and a.name in ("_LOCALE", "_CURRENCY", "_WARNINGS", "_FMT_CACHE", "_WIDTH_CACHE"):
                            err("from-import of state", m, a.name)
        elif isinstance(node, ast.Name) and node.id == "__import__":
            err("__import__", m)
    graph[m] = deps
    if m != "tally.reports":
        for d in deps:
            if d not in mods: err("unknown dep", m, d); continue
            if layer(d) > layer(m): err("layer", m, "->", d)
# cycles
color = {}
def dfs(u, stack):
    color[u] = 1
    for v in graph.get(u, ()):
        if color.get(v) == 1: err("cycle", stack + [u, v])
        elif v not in color: dfs(v, stack + [u])
    color[u] = 2
for m in graph:
    if m not in color: dfs(m, [])
# allowed top-level in reports/
allowed = {"__init__.py", "errors.py", "tables.py", "state.py", "system.py", "formatting", "formatting.py", "model", "model.py",
           "loading", "loading.py", "aggregate", "aggregate.py", "renderers", "cli", "cli.py"}
for e in os.listdir(ROOT):
    if e == "__pycache__": continue
    if e not in allowed: err("unexpected entry", e)
for e in ("errors", "tables", "state", "system"):
    if not os.path.isfile(f"{ROOT}/{e}.py"): err("not single module", e)
# __init__ content
t = ast.parse(open(ROOT + "/__init__.py").read())
for i, n in enumerate(t.body):
    ok = isinstance(n, (ast.Import, ast.ImportFrom)) or (i == 0 and isinstance(n, ast.Expr) and isinstance(n.value, ast.Constant)) or (isinstance(n, ast.Assign) and n.targets[0].id == "__all__")
    if not ok: err("init content", ast.dump(n)[:80])
if os.path.exists(ROOT + "/__main__.py"): err("__main__")
if os.path.exists("/app/tally/reports.py"): err("old module exists")

# ---- single definition, global-state homes
defs = {}
for m, p in mods.items():
    tree = ast.parse(open(p, encoding="utf-8").read())
    for n in tree.body:
        if isinstance(n, (ast.FunctionDef, ast.ClassDef)):
            defs.setdefault(n.name, []).append(m)
for k, v in defs.items():
    if len(v) > 1: err("defined twice", k, v)

# ---- API vs original
spec = importlib.util.spec_from_file_location("reports_orig", "/tmp/orig/reports_orig.py")
orig = importlib.util.module_from_spec(spec)
sys.modules["reports_orig"] = orig
spec.loader.exec_module(orig)
import tally.reports as new
otree = ast.parse(open("/tmp/orig/reports_orig.py", encoding="utf-8").read())
names = []
for n in otree.body:
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)): names.append(n.name)
    elif isinstance(n, ast.Assign): names.append(n.targets[0].id)
    elif isinstance(n, ast.AnnAssign): names.append(n.target.id)
for nm in names:
    if nm.startswith("_"):
        if hasattr(new, nm): err("private exposed", nm)
        continue
    if not hasattr(new, nm): err("missing public", nm); continue
    a, b = getattr(orig, nm), getattr(new, nm)
    if type(a) is not type(b): err("kind", nm, type(a), type(b)); continue
    if inspect.isfunction(a):
        if str(inspect.signature(a)) != str(inspect.signature(b)): err("sig", nm, inspect.signature(a), inspect.signature(b))
        if a.__doc__ != b.__doc__: err("doc", nm)
    elif inspect.isclass(a):
        if a.__doc__ != b.__doc__: err("doc", nm)
        if a.__name__ != b.__name__ or a.__qualname__ != b.__qualname__: err("name", nm)
        if a.__module__ != b.__module__: print("note: module differs for", nm, a.__module__, b.__module__)
        for k, v in vars(a).items():
            if k in ("__module__", "__dict__", "__weakref__", "__doc__", "__firstlineno__", "__static_attributes__"): continue
            if k not in vars(b): err("class attr missing", nm, k)
            elif inspect.isfunction(v):
                try:
                    if str(inspect.signature(v)) != str(inspect.signature(vars(b)[k])): err("sig", nm, k)
                except Exception: pass
    elif nm != "__all__":
        if a != b: err("value", nm)
if orig.__all__ != new.__all__: err("__all__")
if orig.__doc__ != new.__doc__: err("module doc")
print("registered", new.available_formats(aliases=True), orig.available_formats(aliases=True))
if new.available_formats(aliases=True) != orig.available_formats(aliases=True): err("registry order")
print("old public count", len([n for n in names if not n.startswith("_")]))
print("bad =", bad)

